LazyColumn(modifier = Modifier.height({{height}}.dp).semantics { contentDescription = {{label}} }) {
    items(count = {{count}}) { index ->
        Row(
            modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 10.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
        ) {
            MonarchText(text = {{itemLabel}} + " " + (index + 1))
            MonarchText(text = teams[index % teams.size], color = MonarchTheme.colors.textMuted)
        }
    }
}

