LazyColumn(modifier = Modifier.height(320.dp).semantics { contentDescription = "Contacts" }) {
    items(count = 5000) { index ->
        Row(
            modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 10.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
        ) {
            MonarchText(text = "Contact" + " " + (index + 1))
            MonarchText(text = teams[index % teams.size], color = MonarchTheme.colors.textMuted)
        }
    }
}

LazyColumn(modifier = Modifier.height(MonarchTheme.spacing.space24 * 3)) {
    items(items = List(loaded) { it + 1 }, key = { it }) { ticket ->
        MonarchText(text = "Ticket $ticket")
    }
    item(key = "loading", contentType = "loading") {
        MonarchProgress(
            modifier = Modifier.fillMaxWidth(),
            label = "Loading more tickets",
        )
        LaunchedEffect(loaded) { if (loaded < 200) loaded += 50 }
    }
}

LazyVerticalGrid(
    columns = GridCells.Adaptive(MonarchTheme.spacing.space24),
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 3),
) {
    items(items = List(500) { it + 1 }, key = { it }) { item ->
        MonarchCard { MonarchText(text = "Item $item") }
    }
}
